<?php namespace App\Services; use App\Events\PurchaseConfirmed; use App\Models\Booking; use App\Models\Event; use App\Models\TicketCategory; use Illuminate\Support\Facades\DB; use Illuminate\Support\Facades\Cache; use Illuminate\Validation\ValidationException; use App\Jobs\ExpireBookingJob; class BookingService {public function reserve(int $userId,array $data,?string $key):Booking {if($key&&($existing=Booking::where('user_id',$userId)->where('idempotency_key',$key)->first()))return $existing;return DB::transaction(function()use($userId,$data,$key){$event=Event::withoutGlobalScope('publicPublished')->lockForUpdate()->findOrFail($data['event_id']);if($event->status->value!=='published'||$event->starts_at->isPast())throw ValidationException::withMessages(['event_id'=>'الفعالية غير متاحة للشراء.']);$total=0;$resolved=[];$count=0;foreach($data['items'] as $item){$cat=TicketCategory::where('event_id',$event->id)->lockForUpdate()->find($item['ticket_category_id']);if(!$cat)throw ValidationException::withMessages(['items'=>'نوع التذكرة لا يتبع هذه الفعالية.']);if($item['quantity']>$cat->max_per_order||$item['quantity']>$event->max_per_order)throw ValidationException::withMessages(['items'=>'تجاوزت الحد الأقصى للتذاكر.']);$reserved=(int)$cat->activeReservations()->sum('quantity');if($cat->quantity-$cat->sold-$reserved<$item['quantity'])throw ValidationException::withMessages(['items'=>'الكمية المطلوبة غير متوفرة.']);$count+=$item['quantity'];$total+=(float)$cat->price*$item['quantity'];$resolved[]=[$cat,$item['quantity']];}if($count>$event->max_per_order)throw ValidationException::withMessages(['items'=>'تجاوزت الحد الأقصى للتذاكر للطلب.']);$booking=Booking::create(['user_id'=>$userId,'event_id'=>$event->id,'status'=>'paid','total'=>$total,'idempotency_key'=>$key,'paid_at'=>now()]);foreach($resolved as [$cat,$qty]){$booking->items()->create(['ticket_category_id'=>$cat->id,'quantity'=>$qty,'unit_price'=>$cat->price]);$cat->increment('sold',$qty);}DB::afterCommit(fn()=>PurchaseConfirmed::dispatch($booking));DB::afterCommit(fn()=>Cache::tags(['events'])->flush());return $booking->load('items');},3);} 
public function hold(int $userId,array $data,?string $key):Booking {if($key&&($existing=Booking::where('user_id',$userId)->where('idempotency_key',$key)->first()))return $existing;return DB::transaction(function()use($userId,$data,$key){$event=Event::withoutGlobalScope('publicPublished')->lockForUpdate()->findOrFail($data['event_id']);if($event->status->value!=='published'||$event->starts_at->isPast())throw ValidationException::withMessages(['event_id'=>'الفعالية غير متاحة للحجز.']);$total=0;$resolved=[];$count=0;foreach($data['items'] as $row){$cat=TicketCategory::where('event_id',$event->id)->lockForUpdate()->find($row['ticket_category_id']);if(!$cat)throw ValidationException::withMessages(['items'=>'نوع التذكرة لا يتبع هذه الفعالية.']);if($row['quantity']>$cat->max_per_order||$row['quantity']>$event->max_per_order)throw ValidationException::withMessages(['items'=>'تجاوزت الحد الأقصى للتذاكر.']);$reserved=(int)$cat->activeReservations()->sum('quantity');if($cat->quantity-$cat->sold-$reserved<$row['quantity'])throw ValidationException::withMessages(['items'=>'الكمية المطلوبة غير متوفرة.']);$count+=$row['quantity'];$total+=(float)$cat->price*$row['quantity'];$resolved[]=[$cat,$row['quantity']];}if($count>$event->max_per_order)throw ValidationException::withMessages(['items'=>'تجاوزت الحد الأقصى للتذاكر للطلب.']);$expires=now()->addMinutes(10);$booking=Booking::create(['user_id'=>$userId,'event_id'=>$event->id,'status'=>'reserved','total'=>$total,'idempotency_key'=>$key,'expires_at'=>$expires]);foreach($resolved as [$cat,$qty])$booking->items()->create(['ticket_category_id'=>$cat->id,'quantity'=>$qty,'unit_price'=>$cat->price]);DB::afterCommit(fn()=>ExpireBookingJob::dispatch($booking->id)->delay($expires));return $booking->load('items');},3);}
public function confirm(Booking $booking,int $userId):Booking {$paid=DB::transaction(function()use($booking,$userId){$b=Booking::whereKey($booking->id)->lockForUpdate()->firstOrFail();if($b->user_id!==$userId)abort(403);if($b->status->value==='paid')return $b;if($b->status->value!=='reserved'||!$b->expires_at||$b->expires_at->isPast())throw ValidationException::withMessages(['booking'=>'مهلة الحجز انتهت أو لم يعد قابلًا للتأكيد.']);foreach($b->items as $item){$cat=TicketCategory::whereKey($item->ticket_category_id)->lockForUpdate()->firstOrFail();$otherHolds=(int)$cat->activeReservations()->where('booking_id','<>',$b->id)->sum('quantity');if($cat->quantity-$cat->sold-$otherHolds<$item->quantity)throw ValidationException::withMessages(['booking'=>'لم تعد الكمية متاحة.']);$cat->increment('sold',$item->quantity);}$b->update(['status'=>'paid','paid_at'=>now()]);DB::afterCommit(fn()=>PurchaseConfirmed::dispatch($b));DB::afterCommit(fn()=>Cache::tags(['events'])->flush());return $b->fresh('items');},3);return $paid;}
public function release(Booking $b):void{ExpireBookingJob::dispatch($b->id)->delay($b->expires_at);}}
